INSERT INTO `inquiry_messages` (`id`, `inquiry_id`, `sender_id`, `message`, `created_at`) VALUES
(1, 1, 1, 'Hi, do you have the service records for the last three years? Also, is the sunroof working smoothly?', '2026-09-29 20:00:00'),
(2, 1, 2, 'Hello Riya! Yes, all records are with the authorised workshop and I can share copies. The sunroof works perfectly.', '2026-09-30 07:30:00'),
(3, 1, 1, 'Great, thank you. I will send a purchase request shortly.', '2026-09-30 07:45:00'),
(4, 2, 1, 'Is the manufacturer warranty transferable to a new owner?', '2026-09-30 10:30:00'),
(5, 3, 11, 'Hi Aarav, is the Fortuner free of any accident history? Also, do you have all service invoices from Toyota?', '2026-09-30 09:00:00'),
(6, 3, 4, 'Hello Meera! No accident history at all. I have every Toyota service invoice since purchase and can share photos of them.', '2026-09-30 12:30:00'),
(7, 3, 11, 'Great, please share them. I am also considering a pre-purchase inspection through CarZen Services.', '2026-09-30 13:10:00'),
(8, 3, 4, 'Sure, I have uploaded the invoices to the shared drive. Feel free to inspect it any weekend.', '2026-10-01 20:30:00'),
(9, 4, 7, 'Hello Vikram, how old are the tyres and is the insurance transferable? I can visit this weekend.', '2026-09-30 11:00:00'),
(10, 4, 10, 'Hi Sneha. Tyres are 14 months old with ~70% tread. Comprehensive insurance runs till December and can be transferred.', '2026-10-01 09:15:00'),
(11, 4, 7, 'Perfect. I will send a purchase request once I have seen the car.', '2026-10-01 12:10:00'),
(12, 5, 9, 'Hi Priya, what is the battery state of health and what real-world range do you get?', '2026-10-02 08:30:00'),
(13, 6, 8, 'Is there any room on the price of the Thar? I can pay quickly if the deal works.', '2026-09-28 10:00:00'),
(14, 6, 6, 'Hi Karan, the price is already very competitive for 19,800 km. I can drop 10,000 for a quick deal.', '2026-09-28 16:00:00'),
(15, 6, 8, 'Understood. I will think about it and place an order if I decide to go ahead.', '2026-09-30 18:00:00'),
(16, 7, 11, 'How many km/l do you get in the city?', '2026-10-02 21:00:00'),
(17, 8, 8, 'Is it company-maintained? Can I see the service book on a video call?', '2026-10-01 17:00:00'),
(18, 8, 10, 'Yes, serviced at the Hyundai authorised workshop. Happy to do a video call at 7 pm tomorrow.', '2026-10-02 10:30:00'),
(19, 9, 9, 'Does the Creta have any pending loan or hypothecation?', '2026-09-25 09:00:00'),
(20, 9, 4, 'No loan - the car is fully paid and the RC has no hypothecation entry.', '2026-09-25 18:45:00');
